-- ============================================================================
-- Migration: Worldwide Ports Seed from UN/LOCODE (2026-08-01)
-- Source: https://github.com/datasets/un-locode
-- Run: mysql -u user -p haizon < this_file.sql
-- Idempotent -- safe to re-run (INSERT IGNORE)
-- NOTE: Run after geo_countries_seed_20260801.sql
-- ============================================================================

-- 1. Clean up existing duplicates (keep lowest ID)
DELETE p1 FROM `erp_ports` p1
INNER JOIN `erp_ports` p2
ON p1.port_name = p2.port_name AND p1.country_id = p2.country_id AND p1.id > p2.id;

-- 2. Convert TEXT columns to VARCHAR (required for unique index)
ALTER TABLE `erp_ports` MODIFY COLUMN `port_name` VARCHAR(255) NOT NULL;
ALTER TABLE `erp_ports` MODIFY COLUMN `port_code` VARCHAR(255) DEFAULT NULL;

-- 3. Add unique index to prevent future duplicates
ALTER TABLE `erp_ports` ADD UNIQUE INDEX `uq_port_country` (`port_name`, `country_id`);

-- 4. Seed worldwide ports



































